ROOMS.push({
 id:'S3', name:'Probability', paper:'3',
 upLearn:'Probability: Venn diagrams, tree diagrams, conditional probability',
 pearson:'Statistics & Mechanics Year 1: Ch 5 Probability. Year 2: Ch 2 Conditional probability',
 concept:'Probability is about counting carefully and knowing which rule applies. Mutually exclusive events cannot both happen (add the probabilities); independent events do not affect each other (multiply them). Venn diagrams organise overlapping events; tree diagrams organise sequences, especially without replacement. Year 2 adds conditional probability and the formula that links it to the intersection, and the test for independence that follows from it. Set notation — ∩, ∪, the prime for complement — is examinable in its own right. Draw the diagram first; the algebra falls out of the picture.',
 formulae:['P(A ∪ B) = P(A) + P(B) − P(A ∩ B)',
  'Mutually exclusive: P(A ∩ B) = 0, so P(A ∪ B) = P(A) + P(B)',
  'Independent: P(A ∩ B) = P(A) P(B); equivalently P(A | B) = P(A)',
  'Conditional: P(A | B) = P(A ∩ B) / P(B)',
  'Complement: P(A′) = 1 − P(A)',
  'Tree diagrams: multiply along branches, add between branches'],
 videos:[{ch:'TLMaths',q:'TLMaths conditional probability Venn diagram A level'},
  {ch:'ExamSolutions',q:'ExamSolutions tree diagrams without replacement'}],
 examples:[
  {title:'From a Venn diagram: P(A) = 0.6, P(B) = 0.5, P(A ∪ B) = 0.8. Find P(A ∩ B) and P(A | B). Are A and B independent?',
   steps:['P(A ∩ B) = P(A) + P(B) − P(A ∪ B) = 0.6 + 0.5 − 0.8 = 0.3.',
    'P(A | B) = P(A ∩ B)/P(B) = 0.3/0.5 = 0.6.',
    'P(A | B) = 0.6 = P(A).',
    'Since P(A | B) = P(A), the events A and B are independent.']},
  {title:'A bag has 3 red and 5 blue counters. Two are taken without replacement. Find P(at least one red)',
   steps:['P(both blue) = 5/8 × 4/7 = 20/56 = 5/14.',
    '"At least one red" is the complement of "both blue".',
    'P(at least one red) = 1 − 5/14 = 9/14.',
    'Check by direct route: RR + RB + BR = 6/56 + 15/56 + 15/56 = 36/56 = 9/14. ✓']}],
 questions:[
  {q:'A and B are independent with P(A) = 0.4 and P(B) = 0.5. Find P(A ∩ B) and P(A ∪ B).', a:'0.2 and 0.7', sol:'P(A ∩ B) = 0.4 × 0.5 = 0.2. P(A ∪ B) = 0.4 + 0.5 − 0.2 = 0.7.', m:3, d:1,
   hints:['Independent means multiply for the intersection.','Then use the addition rule for the union.','Don\'t double-count the overlap.']},
  {q:'A and B are mutually exclusive with P(A) = 0.3 and P(B) = 0.45. Find P(A ∪ B).', a:'0.75', sol:'Mutually exclusive means P(A ∩ B) = 0, so P(A ∪ B) = 0.3 + 0.45.', m:1, d:1,
   hints:['Mutually exclusive: no overlap.','So just add.','0.3 + 0.45.']},
  {q:'Two fair dice are rolled. Find the probability that the total is 7.', a:'1/6', sol:'Six outcomes total 7 out of 36: (1,6), (2,5), (3,4), (4,3), (5,2), (6,1).', m:2, d:1,
   hints:['There are 36 equally likely outcomes.','List the pairs that add to 7.','There are six of them.']},
  {q:'A bag contains 3 red and 5 blue counters. Two are drawn without replacement. Find P(both red).', a:'3/28', sol:'3/8 × 2/7 = 6/56 = 3/28.', m:2, d:2,
   hints:['Draw a tree diagram.','After one red is taken, 2 red remain out of 7.','Multiply along the branch.']},
  {q:'P(A ∩ B) = 0.12 and P(B) = 0.3. Find P(A | B).', a:'0.4', sol:'0.12/0.3 = 0.4.', m:1, d:1,
   hints:['Use the conditional probability formula.','P(A | B) = P(A ∩ B)/P(B).','Divide.']},
  {q:'P(A) = 0.6, P(B) = 0.5, P(A ∪ B) = 0.8. Find P(A ∩ B) and determine whether A and B are independent.', a:'P(A ∩ B) = 0.3; independent, since 0.6 × 0.5 = 0.3', sol:'P(A ∩ B) = 0.6 + 0.5 − 0.8 = 0.3. P(A)P(B) = 0.3 = P(A ∩ B), so independent.', m:3, d:2,
   hints:['Rearrange the addition rule to find the intersection.','Independence test: does P(A)P(B) equal P(A ∩ B)?','0.6 × 0.5 = 0.3.']},
  {q:'P(B) = 0.5 and P(A ∩ B) = 0.2. Find P(A′ ∩ B).', a:'0.3', sol:'P(A′ ∩ B) = P(B) − P(A ∩ B) = 0.5 − 0.2 = 0.3.', m:2, d:1,
   hints:['Draw a Venn diagram and shade the part of B outside A.','That region is B minus the overlap.','0.5 − 0.2.']},
  {q:'Three fair coins are tossed. Find the probability of at least one head.', a:'7/8', sol:'P(no heads) = (1/2)³ = 1/8. P(at least one head) = 1 − 1/8 = 7/8.', m:2, d:1,
   hints:['"At least one" — think about the complement.','P(all tails) = 1/8.','Subtract from 1.']}],
 exit:[{q:'P(A) = 0.35. Find P(A′).',a:'0.65'},
  {q:'A and B are independent with P(A) = 0.2, P(B) = 0.6. Find P(A ∩ B).',a:'0.12'},
  {q:'On a tree diagram, what do you do with probabilities along a single path?',a:'Multiply them'}]
});

